import React from 'react';
import '../styles/3DAnimation.css';

const Animation3D = () => {
  return (
    <div className="cube-container">
      <div className="cube">
        <div className="cube-face front">ShopAnon</div>
        <div className="cube-face back">Shopping</div>
        <div className="cube-face right">Online</div>
        <div className="cube-face left">Store</div>
        <div className="cube-face top">3D</div>
        <div className="cube-face bottom">Ecommerce</div>
      </div>

      {/* Floating particles for depth effect */}
      <div className="particles">
        {[...Array(12)].map((_, i) => (
          <div key={i} className="particle" style={{ '--delay': `${i * 0.1}s` }}></div>
        ))}
      </div>
    </div>
  );
};

export default Animation3D;
